python3 -c "
import pandas as pd
df = pd.read_csv('/app/data/test_center_logs.csv')
# Get distinct base patterns (without noise)
texts = df['raw_reason_text'].unique()

# Count key pattern types
patterns = {}
for t in texts:
    if '开路' in t or 'open' in t.lower():
        patterns['open'] = patterns.get('open', 0) + 1
    if '短路' in t or 'short' in t.lower() or '桥连' in t:
        patterns['short'] = patterns.get('short', 0) + 1
    if '虚焊' in t or '浮高' in t or 'cold solder' in t.lower() or 'intermittent' in t.lower():
        patterns['cold_solder'] = patterns.get('cold_solder', 0) + 1
    if '接触不良' in t or 'fixture contact' in t.lower() or 'pogo' in t.lower():
        patterns['fixture_contact'] = patterns.get('fixture_contact', 0) + 1
    if '烧录失败' in t or 'flash' in t.lower() or 'program' in t.lower():
        patterns['flash_fail'] = patterns.get('flash_fail', 0) + 1
    if '校验' in t or 'CRC' in t or 'checksum' in t.lower():
        patterns['checksum'] = patterns.get('checksum', 0) + 1
    if 'boot' in t.lower() or '启动' in t or 'OS fail' in t:
        patterns['boot_fail'] = patterns.get('boot_fail', 0) + 1
    if '版本不符' in t or 'version mismatch' in t.lower():
        patterns['version_mismatch'] = patterns.get('version_mismatch', 0) + 1
    if '漏电' in t or 'hipot' in t.lower() or 'leakage' in t.lower() or '绝缘' in t:
        patterns['leakage'] = patterns.get('leakage', 0) + 1
    if '静态电流' in t or 'idle current' in t.lower() or '功耗' in t:
        patterns['current_high'] = patterns.get('current_high', 0) + 1
    if '少件' in t or 'missing' in t.lower():
        patterns['missing'] = patterns.get('missing', 0) + 1
    if '反向' in t or 'reversed' in t.lower() or 'polarity' in t.lower():
        patterns['reversed'] = patterns.get('reversed', 0) + 1
    if '压伤' in t or 'pressure mark' in t.lower():
        patterns['pressure_mark'] = patterns.get('pressure_mark', 0) + 1
    if '静电' in t or 'ESD' in t:
        patterns['esd'] = patterns.get('esd', 0) + 1
    if '探针磨损' in t or 'probe worn' in t.lower():
        patterns['probe_worn'] = patterns.get('probe_worn', 0) + 1
    if '助焊剂' in t or '污染' in t or 'contamination' in t.lower() or 'residue' in t.lower():
        patterns['contamination'] = patterns.get('contamination', 0) + 1
    if '插拔' in t or 'connector wear' in t.lower() or 'SMA' in t or 'insertion loss' in t.lower():
        patterns['connector_wear'] = patterns.get('connector_wear', 0) + 1
    if '校准' in t or 'cal data' in t.lower() or 'nv write' in t.lower():
        patterns['cal_data'] = patterns.get('cal_data', 0) + 1
    if 'BST' in t and ('异常' in t or 'abnormal' in t.lower()):
        patterns['bst_abnormal'] = patterns.get('bst_abnormal', 0) + 1

for k, v in sorted(patterns.items(), key=lambda x: -x[1]):
    print(f'{k}: {v}')
print()

# Check for any texts that don't match any pattern
unmatched = 0
for t in texts:
    matched = False
    for kw in ['开路', 'open', '短路', 'short', '桥连', '虚焊', '浮高', 'cold solder', 'intermittent',
               '接触不良', 'fixture contact', 'pogo', '烧录失败', 'flash', 'program',
               '校验', 'CRC', 'checksum', 'boot', '启动', 'OS fail', '版本不符', 'version mismatch',
               '漏电', 'hipot', 'leakage', '绝缘', '静态电流', 'idle current', '功耗',
               '少件', 'missing', '反向', 'reversed', 'polarity', '压伤', 'pressure mark',
               '静电', 'ESD', '探针磨损', 'probe worn', '助焊剂', '污染', 'contamination', 'residue',
               '插拔', 'connector wear', 'SMA', 'insertion loss', '校准', 'cal data', 'nv write',
               'BST 异常', 'BST abnormal', 'need check']:
        if kw.lower() in t.lower():
            matched = True
            break
    if not matched:
        unmatched += 1
        if unmatched <= 10:
            print(f'UNMATCHED: {repr(t)}')

print(f'Total unmatched: {unmatched}')
"
